final class OwnExcessCommitReplyPDO extends PDO
{
    public string $replyMode='';
    public function commit():bool
    {
        $mode=$this->replyMode;$this->replyMode='';
        if($mode==='before-disconnect')$this->exec('KILL CONNECTION '.(int)$this->query('SELECT CONNECTION_ID()')->fetchColumn());
        $result=parent::commit();
        if($mode==='after-disconnect')$this->exec('KILL CONNECTION '.(int)$this->query('SELECT CONNECTION_ID()')->fetchColumn());
        if($mode==='lost-reply')throw new PDOException('Own accepted COMMIT response lost');
        return $result;
    }
}
